import os
import sys
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

# Global variables
model = None
model_loaded = False
mlflow_tracking_uri = "http://127.0.0.1:5000"
model_type = None  # Will be set at startup

# Define Pydantic models for request/response
class PredictRequest(BaseModel):
    features: list

class PredictBatchRequest(BaseModel):
    samples: list[list]

app = FastAPI()

# Startup event to load model
@app.on_event("startup")
async def startup_event():
    global model, model_loaded, model_type
    import mlflow
    mlflow.set_tracking_uri("http://127.0.0.1:5000")
    from mlflow.sklearn import load_model
    model_uri = "models:/breast-cancer-classifier/1"
    model = load_model(model_uri)
    model_loaded = True
    # Determine model type from the loaded model class
    model_class_name = model.__class__.__name__
    if model_class_name == "LogisticRegression":
        model_type = "logistic_regression"
    elif model_class_name == "SupportVectorClassifier" or model_class_name == "SVC":
        model_type = "svm"
    elif model_class_name == "RandomForestClassifier":
        model_type = "random_forest"
    else:
        model_type = "unknown"
    print(f"Model loaded: {model.__class__.__name__}, type: {model_type}")

# Endpoint 1: POST /predict
@app.post("/predict")
def predict(request: PredictRequest):
    if len(request.features) != 30:
        raise HTTPException(status_code=400, detail="features must contain exactly 30 values")
    prediction = model.predict([[request.features]])[0]
    label = "malignant" if prediction == 0 else "benign"
    return {
        "prediction": int(prediction),
        "prediction_label": label,
        "model_name": "breast-cancer-classifier",
        "model_version": 1
    }

# Endpoint 2: GET /health
@app.get("/health")
def health():
    return {
        "status": "healthy",
        "model_loaded": model_loaded,
        "mlflow_tracking_uri": mlflow_tracking_uri
    }

# Endpoint 3: GET /model-info
@app.get("/model-info")
def model_info():
    return {
        "model_name": "breast-cancer-classifier",
        "model_version": 1,
        "model_stage": "Production",
        "model_type": model_type
    }

# Endpoint 4: POST /predict-batch
@app.post("/predict-batch")
def predict_batch(request: PredictBatchRequest):
    if not request.samples:
        raise HTTPException(status_code=422, detail="samples list is empty")
    for sample in request.samples:
        if len(sample) != 30:
            raise HTTPException(status_code=400, detail="Each sample must have exactly 30 features")
    predictions = []
    for sample in request.samples:
        pred = model.predict([sample])[0]
        label = "malignant" if pred == 0 else "benign"
        predictions.append({
            "prediction": int(pred),
            "prediction_label": label
        })
    return {
        "predictions": predictions,
        "count": len(request.samples),
        "model_name": "breast-cancer-classifier",
        "model_version": 1
    }
EOF"}

